#include "ordermanagerwidget.h"
#include "netclient.h"
#include "protocol.h"
#include <QtWidgets>

OrderManagerWidget::OrderManagerWidget(NetClient*n,QWidget*p):QWidget(p),m_net(n){setObjectName("orderPage");buildUi();loadFilterOptions();loadPage(1);}
void OrderManagerWidget::buildUi(){auto*r=new QVBoxLayout(this);r->setContentsMargins(22,16,22,16);r->setSpacing(10);m_summary=new QLabel("当前页统计",this);m_summary->setObjectName("orderSummary");m_summary->setFixedHeight(60);r->addWidget(m_summary);auto*tl=new QHBoxLayout;QList<QPair<QString,QString>>ss={{"全部",""},{"已预约","reserved"},{"充电中","charging"},{"待支付","pending_payment"},{"已结算","settled"},{"已取消","cancelled"}};m_status=new QComboBox(this);for(auto&s:ss){m_status->addItem(s.first,s.second);auto*b=new QPushButton(s.first,this);b->setObjectName("orderStatusTab");b->setCheckable(true);connect(b,&QPushButton::clicked,this,[this,s]{selectStatus(s.second);});m_tabs<<b;tl->addWidget(b);}tl->addStretch();r->addLayout(tl);auto*bar=new QFrame(this);bar->setObjectName("orderToolbar");auto*bl=new QHBoxLayout(bar);bl->setContentsMargins(12,9,12,9);m_orderNo=new QLineEdit;m_orderNo->setPlaceholderText("搜索订单号");m_phone=new QLineEdit;m_phone->setPlaceholderText("手机号 / 用户");m_station=new QComboBox;m_station->addItem("全部电站",0);m_dateRange=new QComboBox;m_dateRange->addItems({"今天","近7天","近30天","自定义"});m_dateRange->setCurrentIndex(2);auto*more=new QPushButton("更多筛选");more->setCheckable(true);auto*refresh=new QPushButton("刷新");bl->addWidget(m_orderNo,2);bl->addWidget(m_phone,2);bl->addWidget(m_station);bl->addWidget(m_dateRange);bl->addWidget(more);bl->addWidget(refresh);r->addWidget(bar);m_morePanel=new QFrame;auto*ml=new QHBoxLayout(m_morePanel);m_pile=new QComboBox;m_pile->addItem("全部电桩",0);m_start=new QDateTimeEdit;m_end=new QDateTimeEdit;for(auto*e:{m_start,m_end}){e->setCalendarPopup(true);e->setDisplayFormat("yyyy-MM-dd HH:mm");}auto*go=new QPushButton("查询");auto*clear=new QPushButton("重置");ml->addWidget(new QLabel("电桩"));ml->addWidget(m_pile);ml->addWidget(new QLabel("开始"));ml->addWidget(m_start);ml->addWidget(new QLabel("结束"));ml->addWidget(m_end);ml->addWidget(go);ml->addWidget(clear);m_morePanel->hide();r->addWidget(m_morePanel);auto*body=new QHBoxLayout;m_table=new QTableWidget(0,8);m_table->setHorizontalHeaderLabels({"订单号","用户","充电位置","时长","金额","状态","开始时间","操作"});auto*h=m_table->horizontalHeader();for(int i=0;i<8;++i)h->setSectionResizeMode(i,QHeaderView::Fixed);h->setSectionResizeMode(2,QHeaderView::Stretch);int w[]={130,105,160,75,80,75,130,55};for(int i=0;i<8;++i)if(i!=2)m_table->setColumnWidth(i,w[i]);m_table->setHorizontalScrollBarPolicy(Qt::ScrollBarAlwaysOff);m_table->verticalHeader()->setVisible(false);m_table->verticalHeader()->setDefaultSectionSize(56);m_table->setSelectionBehavior(QAbstractItemView::SelectRows);m_table->setEditTriggers(QAbstractItemView::NoEditTriggers);body->addWidget(m_table,1);m_detailPanel=new QFrame;m_detailPanel->setObjectName("orderDetailPanel");m_detailPanel->setFixedWidth(360);auto*dl=new QVBoxLayout(m_detailPanel);auto*dh=new QHBoxLayout;auto*dt=new QLabel("订单详情");dt->setObjectName("orderDetailTitle");auto*x=new QPushButton("×");x->setObjectName("orderDetailClose");x->setFixedSize(30,30);dh->addWidget(dt);dh->addStretch();dh->addWidget(x);dl->addLayout(dh);m_detailContent=new QLabel;m_detailContent->setWordWrap(true);m_detailContent->setAlignment(Qt::AlignTop);dl->addWidget(m_detailContent,1);m_detailPanel->hide();body->addWidget(m_detailPanel);r->addLayout(body,1);auto*pg=new QHBoxLayout;m_total=new QLabel;m_pageLabel=new QLabel;m_prev=new QPushButton("上一页");m_next=new QPushButton("下一页");pg->addWidget(m_total);pg->addStretch();pg->addWidget(m_prev);pg->addWidget(m_pageLabel);pg->addWidget(m_next);r->addLayout(pg);applyDateRange(2);connect(more,&QPushButton::toggled,m_morePanel,&QWidget::setVisible);connect(refresh,&QPushButton::clicked,this,[this]{loadPage(m_page);});connect(go,&QPushButton::clicked,this,&OrderManagerWidget::query);connect(clear,&QPushButton::clicked,this,&OrderManagerWidget::reset);connect(m_dateRange,QOverload<int>::of(&QComboBox::currentIndexChanged),this,&OrderManagerWidget::applyDateRange);connect(x,&QPushButton::clicked,m_detailPanel,&QWidget::hide);connect(m_prev,&QPushButton::clicked,this,[this]{loadPage(m_page-1);});connect(m_next,&QPushButton::clicked,this,[this]{loadPage(m_page+1);});connect(m_table,&QTableWidget::cellDoubleClicked,this,&OrderManagerWidget::showDetail);connect(m_table,&QTableWidget::cellClicked,this,[this](int a,int b){if(b==8)showDetail(a,b);});selectStatus("");}
void OrderManagerWidget::selectStatus(const QString&s){m_status->setCurrentIndex(qMax(0,m_status->findData(s)));for(auto*b:m_tabs){bool on=b->text()==m_status->currentText();b->setProperty("selected",on);b->setChecked(on);b->style()->unpolish(b);b->style()->polish(b);}if(isVisible())loadPage(1);}
void OrderManagerWidget::applyDateRange(int i){QDate d=QDate::currentDate();if(i==0)m_start->setDateTime(d.startOfDay());if(i==1)m_start->setDateTime(d.addDays(-6).startOfDay());if(i==2)m_start->setDateTime(d.addDays(-29).startOfDay());m_end->setDateTime(d.endOfDay());if(i==3)m_morePanel->show();}
void OrderManagerWidget::query(){loadPage(1);}void OrderManagerWidget::reset(){m_orderNo->clear();m_phone->clear();m_station->setCurrentIndex(0);m_pile->setCurrentIndex(0);m_dateRange->setCurrentIndex(2);selectStatus("");}
void OrderManagerWidget::loadFilterOptions(){if(!m_net)return;auto s=m_net->request(Protocol::makeRequest(Protocol::MsgType::AdminStationList));for(auto v:s.value("data").toObject().value("list").toArray()){auto o=v.toObject();m_station->addItem(o.value("name").toString(),o.value("id").toInt());}auto p=m_net->request(Protocol::makeRequest(Protocol::MsgType::AdminPileList));for(auto v:p.value("data").toObject().value("list").toArray()){auto o=v.toObject();m_pile->addItem(o.value("code").toString(),o.value("id").toInt());}}
QString OrderManagerWidget::valueText(const QJsonObject&o,const QString&k)const{return o.value(k).toString();}QString OrderManagerWidget::statusText(const QString&s)const{static QHash<QString,QString>m{{"reserved","已预约"},{"charging","充电中"},{"pending_payment","待支付"},{"settled","已结算"},{"cancelled","已取消"}};return m.value(s,s);}QString OrderManagerWidget::formatDuration(qint64 s)const{return s<=0?"--":s>=3600?QString("%1h %2m").arg(s/3600).arg(s%3600/60):QString("%1 min").arg(s/60);}
void OrderManagerWidget::loadPage(int page){if(!m_net)return;QJsonObject q{{"page",page},{"page_size",20},{"order_no",m_orderNo->text().trimmed()},{"phone",m_phone->text().trimmed()},{"station_id",m_station->currentData().toInt()},{"pile_id",m_pile->currentData().toInt()},{"status",m_status->currentData().toString()},{"start_time",m_start->dateTime().toString(Qt::ISODate)},{"end_time",m_end->dateTime().toString(Qt::ISODate)}};auto z=m_net->request(Protocol::makeRequest(Protocol::MsgType::AdminOrderList,q));if(z.value("code").toInt(-1)!=Protocol::Ok){QMessageBox::warning(this,"查询失败",z.value("msg").toString());return;}auto d=z.value("data").toObject();m_page=d.value("page").toInt(page);m_totalCount=d.value("total").toInt();auto a=d.value("list").toArray();m_table->setRowCount(a.size());double e=0,m=0,t=0;for(int i=0;i<a.size();++i){auto o=a[i].toObject();double k=o.value("kwh").toDouble(),v=o.value("amount").toDouble();qint64 sec=o.value("duration_seconds").toInteger();e+=k;m+=v;t+=sec;QString u=valueText(o,"nickname");if(u.isEmpty())u=valueText(o,"phone");if(u.size()>7)u=u.left(3)+"****"+u.right(4);QString process=QString("%1 kWh").arg(k,0,'f',2);if(!o.value("start_soc").isNull())process=QString("%1% → %2%\n%3").arg(o.value("start_soc").toInt()).arg(o.value("target_soc").toInt()).arg(process);QStringList vs={valueText(o,"order_no"),u.isEmpty()?"--":u,valueText(o,"station_name")+"\n"+valueText(o,"pile_code"),formatDuration(sec),QString("¥%1").arg(v,0,'f',2),statusText(valueText(o,"status")),valueText(o,"start_time"),"详情"};for(int c=0;c<8;++c)m_table->setItem(i,c,new QTableWidgetItem(vs[c]));}m_summary->setText(QString("当前页统计     订单数  %1       充电量  %2 kWh       订单金额  ¥%3       平均时长  %4 min").arg(a.size()).arg(e,0,'f',2).arg(m,0,'f',2).arg(a.size()?QString::number(t/a.size()/60.0,'f',0):"--"));m_total->setText(QString("共 %1 条").arg(m_totalCount));m_pageLabel->setText(QString("第 %1 页").arg(m_page));m_prev->setEnabled(m_page>1);m_next->setEnabled(m_page*20<m_totalCount);}
void OrderManagerWidget::showDetail(int row,int){if(!m_net||!m_table->item(row,0))return;auto z=m_net->request(Protocol::makeRequest("admin_order_detail",{{"order_no",m_table->item(row,0)->text()}}));if(z.value("code").toInt(-1)==Protocol::Ok){renderDetail(z.value("data").toObject());m_detailPanel->show();}}
void OrderManagerWidget::renderDetail(const QJsonObject&o){double k=o.value("kwh").toDouble();qint64 s=o.value("duration_seconds").toInteger();QString p=s>0?QString("约 %1 kW").arg(k/(s/3600.0),0,'f',1):"--";m_detailContent->setText(QString("%1\n[%2]\n\n充电信息\n电站  %3\n电桩  %4\n充电量  %5 kWh\n充电时长  %6\n平均功率  %7\n按订单电量与时长估算\n\n费用\n单价  ¥%8/kWh\n订单金额  ¥%9\n\n订单流程\n● 开始充电\n  %10\n│\n● 充电结束\n  %11\n│\n● %2").arg(valueText(o,"order_no"),statusText(valueText(o,"status")),valueText(o,"station_name"),valueText(o,"pile_code"),QString::number(k,'f',2),formatDuration(s),p,QString::number(o.value("unit_price").toDouble(),'f',2),QString::number(o.value("amount").toDouble(),'f',2),valueText(o,"start_time"),valueText(o,"end_time")));}
